// Publisher Program QBR data pack (advertiser-style structure)
const NODE_PAYLOAD = 'yoy data extraction1';
const NODE_CURRENT = 'Collect Publisher Current';
const NODE_PREVIOUS = 'Collect Publisher Previous';
const NODE_CURRENT_DIGITAL_WALLETS = 'Collect Publisher Digital Wallets Current';
const NODE_PREVIOUS_DIGITAL_WALLETS = 'Collect Publisher Digital Wallets Previous';
const NODE_PROGRAM_STATUS = 'Collect Publisher Program Status';
const COMPETITOR_CURRENT_NODES = [
  'Collect Competitor 1 Current',
  'Collect Competitor 2 Current',
  'Collect Competitor 3 Current',
  'Collect Competitor 4 Current',
];
const COMPETITOR_PREVIOUS_NODES = [
  'Collect Competitor 1 Previous',
  'Collect Competitor 2 Previous',
  'Collect Competitor 3 Previous',
  'Collect Competitor 4 Previous',
];
const COMPETITOR_PROGRAM_STATUS_NODES = [
  'Collect Competitor 1 Program Status',
  'Collect Competitor 2 Program Status',
  'Collect Competitor 3 Program Status',
  'Collect Competitor 4 Program Status',
];

const LOCALE = 'en-GB';
const DISPLAY_TOP_LIMIT = 12;
const API_SCOPE_LIMIT = 120;
const MOVER_LIMIT = 10;
const BRAND_NEW_LIMIT = 10;
const TOP_PROGRAM_COMPETITOR_LIMIT = 10;
const SIGNAL_LIMIT = 10;
const RISK_LIMIT = 10;
const SUPPORTED_CURRENCIES = new Set(['GBP', 'EUR', 'USD', 'AUD', 'SEK', 'NOK', 'DKK', 'ISK', 'PLN']);

function safeNum(v) {
  if (v === null || v === undefined || v === '') return 0;
  if (typeof v === 'number') return Number.isFinite(v) ? v : 0;

  let s = String(v).trim().replace(/[^\d,.-]/g, '').replace(/\s+/g, '');
  if (!s) return 0;

  const lastComma = s.lastIndexOf(',');
  const lastDot = s.lastIndexOf('.');

  if (lastComma > -1 && lastDot > -1) {
    if (lastComma > lastDot) {
      s = s.replace(/\./g, '');
      const i = s.lastIndexOf(',');
      s = s.slice(0, i).replace(/,/g, '') + '.' + s.slice(i + 1);
    } else {
      s = s.replace(/,/g, '');
    }
  } else if (lastComma > -1) {
    const decDigits = s.length - lastComma - 1;
    if (decDigits >= 1 && decDigits <= 2) {
      s = s.slice(0, lastComma).replace(/,/g, '') + '.' + s.slice(lastComma + 1);
    } else {
      s = s.replace(/,/g, '');
    }
  } else if (lastDot > -1) {
    const decDigits = s.length - lastDot - 1;
    if (!(decDigits >= 1 && decDigits <= 2)) s = s.replace(/\./g, '');
  }

  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
}

function normalizeCurrencyCode(code) {
  const c = String(code || '').trim().toUpperCase();
  return SUPPORTED_CURRENCIES.has(c) ? c : '';
}

function getCurrencySymbol(code) {
  switch (String(code || '').toUpperCase()) {
    case 'GBP': return '\u00A3';
    case 'EUR': return '\u20AC';
    case 'USD': return '$';
    case 'AUD': return 'A$';
    case 'PLN': return 'z\u0142';
    case 'SEK':
    case 'NOK':
    case 'DKK':
    case 'ISK': return 'kr';
    default: return '';
  }
}

function fmtInt(v) {
  return Math.round(safeNum(v)).toLocaleString(LOCALE);
}

function fmtMoney0(v, symbol) {
  const n = Math.round(safeNum(v));
  const sign = n < 0 ? '-' : '';
  return sign + symbol + Math.abs(n).toLocaleString(LOCALE);
}

function fmtMoney2(v, symbol) {
  const n = safeNum(v);
  const sign = n < 0 ? '-' : '';
  return sign + symbol + Math.abs(n).toLocaleString(LOCALE, {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  });
}

function fmtRatio2(v) {
  const n = Number(v);
  if (!Number.isFinite(n)) return 'N/A';
  return n.toLocaleString(LOCALE, { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + 'x';
}

function fmtPct(v) {
  if (v === null || v === undefined || Number.isNaN(v)) return 'N/A';
  const n = Number(v);
  const sign = n > 0 ? '+' : '';
  return sign + n.toFixed(1) + '%';
}

function varianceTone(v) {
  if (v === null || v === undefined || Number.isNaN(v)) return 'na';
  const n = Number(v);
  if (n > 0) return 'positive';
  if (n < 0) return 'negative';
  return 'neutral';
}

function varianceColorHex(v) {
  const tone = varianceTone(v);
  if (tone === 'positive') return '#1a7f37';
  if (tone === 'negative') return '#d93025';
  return '#fbbc04';
}

function fmtVarianceCell(v) {
  const base = fmtPct(v);
  const tone = varianceTone(v);
  if (tone === 'positive') return '▲ ' + base;
  if (tone === 'negative') return '▼ ' + base;
  return base;
}

function fmtAbsPct(v) {
  if (v === null || v === undefined || Number.isNaN(v)) return 'N/A';
  return Number(v).toFixed(1) + '%';
}

function fmtWholePct(v) {
  if (v === null || v === undefined || Number.isNaN(v)) return 'N/A';
  return Math.round(Number(v)).toLocaleString(LOCALE) + '%';
}

function yoyPct(current, previous) {
  if (!previous) return null;
  return ((current - previous) / previous) * 100;
}

function formatUtcDate(date) {
  return date.toISOString().slice(0, 10);
}

function normalizeWeekLabel(value, fallbackIndex) {
  const raw = String(value || '').trim();
  if (!raw) return fallbackIndex === undefined ? '' : 'Bucket ' + String(fallbackIndex + 1);

  const compact = raw.replace(/[^0-9]/g, '');
  let candidate = raw;
  if (/^\d{8}$/.test(compact)) {
    candidate = compact.slice(0, 4) + '-' + compact.slice(4, 6) + '-' + compact.slice(6, 8);
  } else {
    const isoMatch = raw.match(/\d{4}-\d{2}-\d{2}/);
    if (isoMatch) candidate = isoMatch[0];
  }

  const parsed = /^\d{4}-\d{2}-\d{2}$/.test(candidate)
    ? new Date(candidate + 'T00:00:00Z')
    : new Date(candidate);
  if (!Number.isNaN(parsed.getTime())) {
    const day = parsed.getUTCDay();
    const daysSinceMonday = (day + 6) % 7;
    parsed.setUTCDate(parsed.getUTCDate() - daysSinceMonday);
    return formatUtcDate(parsed);
  }
  return raw;
}

function pickWeekLabel(item, fallbackIndex) {
  if (!item || typeof item !== 'object') return normalizeWeekLabel('', fallbackIndex);
  const keys = [
    'week',
    'Week',
    'weekStart',
    'weekStartDate',
    'period',
    'Period',
    'date',
    'Date',
    'startDate',
    'fromDate',
    'intervalStart',
    'reportDate',
    'transactionDate',
    'eventDate'
  ];
  for (const key of keys) {
    if (item[key] !== undefined && item[key] !== null && String(item[key]).trim()) {
      return normalizeWeekLabel(item[key], fallbackIndex);
    }
  }
  return normalizeWeekLabel('', fallbackIndex);
}

function getRows(nodeJson) {
  if (!nodeJson || typeof nodeJson !== 'object') return [];
  if (Array.isArray(nodeJson.allItems)) return nodeJson.allItems;
  if (Array.isArray(nodeJson.items)) return nodeJson.items;
  if (Array.isArray(nodeJson.data)) return nodeJson.data;
  if (Array.isArray(nodeJson.rows)) return nodeJson.rows;
  return [];
}

const PROGRAM_CONNECTION_STATUS_LABELS = {
  0: 'Not Connected',
  1: 'Under Consideration',
  2: 'Hold Under Consideration',
  3: 'Accepted',
  4: 'Ended',
  5: 'Denied',
  6: 'Hold Accepted',
  9: 'Ending',
};

const PROGRAM_CONNECTION_STATUS_ORDER = {
  3: 0,
  1: 1,
  2: 2,
  0: 3,
  6: 4,
  9: 5,
  4: 6,
  5: 7,
};

const PROGRAM_CONNECTION_STATUS_FALLBACK_ORDER = {
  accepted: 0,
  'under consideration': 1,
  'hold under consideration': 2,
  'hold uc': 2,
  'not connected': 3,
  'hold accepted': 4,
  ending: 5,
  ended: 6,
  denied: 7,
  rejected: 7,
};

function isoDateOnly(value) {
  const text = String(value || '').trim();
  if (!text) return '';
  const isoMatch = text.match(/\d{4}-\d{2}-\d{2}/);
  if (isoMatch) return isoMatch[0];
  const compact = text.replace(/[^0-9]/g, '');
  if (/^\d{8}$/.test(compact)) return compact.slice(0, 4) + '-' + compact.slice(4, 6) + '-' + compact.slice(6, 8);
  const parsed = new Date(text);
  if (!Number.isNaN(parsed.getTime())) return parsed.toISOString().slice(0, 10);
  return '';
}

function programConnectionStatusLabel(statusId, fallback) {
  const key = String(statusId ?? '').trim();
  if (Object.prototype.hasOwnProperty.call(PROGRAM_CONNECTION_STATUS_LABELS, key)) return PROGRAM_CONNECTION_STATUS_LABELS[key];
  const fallbackText = String(fallback || '').trim();
  const fallbackKey = fallbackText.toLowerCase();
  if (Object.prototype.hasOwnProperty.call(PROGRAM_CONNECTION_STATUS_FALLBACK_ORDER, fallbackKey)) {
    if (fallbackKey === 'hold uc') return 'Hold Under Consideration';
    if (fallbackKey === 'rejected') return 'Denied';
    return fallbackText.replace(/^under consideration$/i, 'Under Consideration');
  }
  if (fallbackText && !/^(none|pending)$/i.test(fallbackText)) return fallbackText;
  return key ? 'Unknown (' + key + ')' : 'Unknown';
}

function programConnectionStatusRank(statusId, statusLabel) {
  const key = String(statusId ?? '').trim();
  if (Object.prototype.hasOwnProperty.call(PROGRAM_CONNECTION_STATUS_ORDER, key)) return PROGRAM_CONNECTION_STATUS_ORDER[key];
  const labelKey = String(statusLabel || '').trim().toLowerCase();
  if (Object.prototype.hasOwnProperty.call(PROGRAM_CONNECTION_STATUS_FALLBACK_ORDER, labelKey)) return PROGRAM_CONNECTION_STATUS_FALLBACK_ORDER[labelKey];
  return 99;
}

function buildProgramConnectionStatusTable(rows, cutoffDate) {
  const cutoff = isoDateOnly(cutoffDate);
  return (rows || [])
    .map((row) => {
      const createdDate = isoDateOnly(row.createdDate || row['Created Date']);
      const statusId = row.statusId ?? row['Status ID'];
      return {
        createdDate,
        programId: String(row.id || row.programId || row['Program ID'] || '').trim(),
        programName: String(row.name || row.programName || row['Program Name'] || '').trim(),
        connectionStatus: programConnectionStatusLabel(statusId, row.connectionStatus || row.statusName || row.status),
      };
    })
    .filter((row) => (row.programId || row.programName) && (!cutoff || (row.createdDate && row.createdDate >= cutoff)))
    .sort((a, b) => {
      const statusOrder = {
        Accepted: 1,
        'Hold Accepted': 2,
        'Under consideration': 3,
        'Hold Under Consideration': 4,
        'Not Connected': 5,
        Ended: 6,
        Denied: 7,
      };
      const byStatus = (statusOrder[a.connectionStatus] || 99) - (statusOrder[b.connectionStatus] || 99);
      if (byStatus !== 0) return byStatus;
      const byDate = String(b.createdDate || '').localeCompare(String(a.createdDate || ''));
      if (byDate !== 0) return byDate;
      return String(a.programName || '').localeCompare(String(b.programName || ''));
    })
    .map((row) => ({
      'Program ID': row.programId || '-',
      'Program Name': row.programName || '-',
      'Connection Status': row.connectionStatus || 'Unknown',
    }));
}

function normalizeGapStatus(status) {
  const text = String(status || '').trim();
  if (!text) return 'No Connection';
  if (/^(not connected|not connected yet|none|unknown)$/i.test(text)) return 'No Connection';
  if (/^hold uc$/i.test(text)) return 'Under consideration';
  if (/^hold accepted$/i.test(text)) return 'Hold Accepted';
  return text;
}

function statusKeyFromParts(programId, programName) {
  const id = String(programId || '').trim();
  if (id && id !== '-') return id;
  return String(programName || '').trim().toLowerCase();
}

function filterProgramStatusRowsByCutoff(rows, cutoffDate) {
  const cutoff = isoDateOnly(cutoffDate);
  if (!cutoff) return rows || [];
  return (rows || []).filter((row) => {
    if (!row || typeof row !== 'object') return false;
    const createdDate = isoDateOnly(row.createdDate || row['Created Date']);
    return Boolean(createdDate && createdDate >= cutoff);
  });
}

function buildProgramStatusMap(rows, cutoffDate) {
  const map = new Map();
  for (const row of filterProgramStatusRowsByCutoff(rows, cutoffDate)) {
    const programId = row.id || row.programId || row['Program ID'];
    const programName = row.name || row.programName || row['Program Name'];
    const key = statusKeyFromParts(programId, programName);
    if (!key) continue;
    const status = normalizeGapStatus(programConnectionStatusLabel(row.statusId ?? row['Status ID'], row.connectionStatus || row.statusName || row.status));
    map.set(key, status);
  }
  return map;
}

function deriveGapStatus(program, statusMap) {
  if (program && safeNum(program.publisherCommission) > 0) return 'Pub Comm';
  if (program && safeNum(program.clicks) > 0) return 'Clicks';
  const key = program ? statusKeyFromParts(program.programId, program.programName) : '';
  return normalizeGapStatus((key && statusMap.get(key)) || 'No Connection');
}

function classifyGap(primaryStatus) {
  const normalized = normalizeGapStatus(primaryStatus);
  if (normalized === 'Accepted') return { type: 'Activation', action: 'Activate' };
  if (normalized === 'Clicks') return { type: 'Click Leakage', action: 'Fix tracking / conversion' };
  if (normalized === 'No Connection') return { type: 'Application', action: 'Apply' };
  if (/^(Denied|Ended|Ending|Hold Accepted|On Hold)$/i.test(normalized)) return { type: 'Recovery', action: 'Recover' };
  if (/under consideration/i.test(normalized)) return { type: 'Pending', action: 'Monitor' };
  return { type: 'Review', action: 'Review' };
}

function buildProgramGapAnalysisTable() {
  const primaryLabel = String(
    payload.clientName ||
    payload.programName ||
    payload.clientUsername ||
    'Primary Publisher'
  ).trim() || 'Primary Publisher';
  const competitorLabels = competitorProgramGroups.slice(0, 4).map((group, index) =>
    String(group.label || ('Comp. ' + String.fromCharCode(65 + index))).trim()
  );
  while (competitorLabels.length < 4) competitorLabels.push('Comp. ' + String.fromCharCode(65 + competitorLabels.length));

  const gapStatusCutoffDate = payload.programStatusCreatedFromDate || payload.programStatusCreatedFromDateRaw;
  const primaryGapStatusRows = filterProgramStatusRowsByCutoff(programStatusRows, gapStatusCutoffDate);
  const competitorGapStatusRows = competitorProgramGroups.slice(0, 4).map((group) => filterProgramStatusRowsByCutoff(group.statusRows || [], gapStatusCutoffDate));
  const primaryStatusByKey = buildProgramStatusMap(primaryGapStatusRows);
  const competitorStatusByKey = competitorGapStatusRows.map((rows) => buildProgramStatusMap(rows));
  const primaryByKey = new Map(currentPrograms.map((program) => [program.key, program]));
  const competitorByKey = competitorProgramGroups.slice(0, 4).map((group) => new Map(group.programs.map((program) => [program.key, program])));
  const programsByKey = new Map();

  const rememberProgram = (key, programId, programName) => {
    if (!key || programsByKey.has(key)) return;
    programsByKey.set(key, {
      key,
      programId: String(programId || '-').trim() || '-',
      programName: String(programName || programId || key).trim() || key,
    });
  };

  currentPrograms.forEach((program) => rememberProgram(program.key, program.programId, program.programName));
  competitorProgramGroups.slice(0, 4).forEach((group) => group.programs.forEach((program) => rememberProgram(program.key, program.programId, program.programName)));
  for (const row of primaryGapStatusRows || []) {
    const programId = row.id || row.programId || row['Program ID'];
    const programName = row.name || row.programName || row['Program Name'];
    rememberProgram(statusKeyFromParts(programId, programName), programId, programName);
  }
  competitorGapStatusRows.forEach((rows) => {
    for (const row of rows || []) {
      const programId = row.id || row.programId || row['Program ID'];
      const programName = row.name || row.programName || row['Program Name'];
      rememberProgram(statusKeyFromParts(programId, programName), programId, programName);
    }
  });

  return Array.from(programsByKey.values())
    .map((programRef) => {
      const primaryProgram = primaryByKey.get(programRef.key);
      const primaryStatus = deriveGapStatus(primaryProgram || programRef, primaryStatusByKey);
      const competitorStatuses = competitorByKey.map((map, index) =>
        deriveGapStatus(map.get(programRef.key), competitorStatusByKey[index])
      );
      const competitorPubComm = competitorByKey.reduce((sum, map) => {
        const competitorProgram = map.get(programRef.key);
        return sum + safeNum(competitorProgram && competitorProgram.publisherCommission);
      }, 0);
      const gap = classifyGap(primaryStatus);
      return {
        key: programRef.key,
        programName: programRef.programName,
        programId: programRef.programId,
        primaryStatus,
        competitorStatuses,
        competitorPubComm,
        gapType: gap.type,
        recommendedAction: gap.action,
        competitorPubCommPublisherCount: competitorStatuses.filter((status) => status === 'Pub Comm').length,
      };
    })
    .filter((row) => row.primaryStatus !== 'Pub Comm')
    .filter((row) => row.competitorPubComm > 0 || row.primaryStatus === 'Clicks' || row.primaryStatus !== 'No Connection')
    .sort((a, b) => {
      if (b.competitorPubComm !== a.competitorPubComm) return b.competitorPubComm - a.competitorPubComm;
      const statusPriority = { Accepted: 1, Clicks: 2, 'No Connection': 3, Denied: 4, Ended: 5, 'Hold Accepted': 6 };
      const byStatus = (statusPriority[a.primaryStatus] || 99) - (statusPriority[b.primaryStatus] || 99);
      if (byStatus !== 0) return byStatus;
      return a.programName.localeCompare(b.programName);
    })
    .map((row) => ({
      'Program Name': row.programName,
      'Program ID': row.programId || '-',
      [primaryLabel]: row.primaryStatus,
      ...Object.fromEntries(competitorLabels.map((label, index) => [label, row.competitorStatuses[index] || 'No Connection'])),
      'Competitor Pub Comm': fmtMoney0(row.competitorPubComm, currencySymbol),
      'Gap Type': row.gapType,
      'Recommended Action': row.recommendedAction,
    }));
}

function buildProgramGapAnalysisSummaryTable(rows) {
  const summary = new Map();
  for (const row of rows || []) {
    const status = String(row['Gap Type'] || 'Review').trim() || 'Review';
    const existing = summary.get(status) || { count: 0, commission: 0 };
    existing.count += 1;
    existing.commission += safeNum(row['Competitor Pub Comm']);
    summary.set(status, existing);
  }
  return Array.from(summary.entries())
    .map(([gapType, value]) => ({
      'Gap Type': gapType,
      Programs: fmtInt(value.count),
      'Competitor Pub Comm': fmtMoney0(value.commission, currencySymbol),
    }));
}

function pickProgramId(item) {
  const candidates = [
    item.programId,
    item.program && item.program.id,
    item.campaignId,
    item.offerId,
    item.advertiserProgramId,
    item.programID,
    item.id,
  ];
  for (const c of candidates) {
    const value = String(c || '').trim();
    if (value) return value;
  }
  return '';
}

function pickSourceId(item) {
  const candidates = [
    item.sourceId,
    item.sourceID,
    item.source && item.source.id,
    item.siteId,
    item.siteID,
    item.publisherSiteId,
    item.affiliateSiteId,
  ];
  for (const c of candidates) {
    const value = String(c || '').trim();
    if (value) return value;
  }
  return '';
}

function pickProgramName(item, fallbackId) {
  const candidates = [
    item.programName,
    item.program && item.program.name,
    item.campaignName,
    item.offerName,
    item.programDisplayName,
    item.name,
  ];
  for (const c of candidates) {
    const value = String(c || '').trim();
    if (value) return value;
  }
  return fallbackId ? ('Program ' + fallbackId) : 'Unknown Program';
}

const LOWER_KEY_CACHE = new WeakMap();
const METRICS_CACHE = new WeakMap();

function findNumericByKeys(obj, keys) {
  if (!obj || typeof obj !== 'object') return 0;
  let best = 0;
  let byLower = LOWER_KEY_CACHE.get(obj);
  if (!byLower) {
    byLower = Object.create(null);
    for (const k of Object.keys(obj)) byLower[k.toLowerCase()] = k;
    LOWER_KEY_CACHE.set(obj, byLower);
  }
  for (const key of keys) {
    const rawKey = byLower[String(key).toLowerCase()];
    if (!rawKey) continue;
    best = Math.max(best, safeNum(obj[rawKey]));
  }
  return best;
}

function collectCommissionLikeNumbers(node, out, depth = 0) {
  if (depth > 4 || node === null || node === undefined) return;
  if (typeof node === 'number' || typeof node === 'string') {
    const n = safeNum(node);
    if (n > 0) out.push(n);
    return;
  }
  if (Array.isArray(node)) {
    for (const child of node) collectCommissionLikeNumbers(child, out, depth + 1);
    return;
  }
  if (typeof node !== 'object') return;

  for (const [key, value] of Object.entries(node)) {
    const k = String(key || '').toLowerCase();
    if (k.includes('rate') || k.includes('ratio') || k.includes('percent') || k.includes('pct')) continue;
    const looksCommissionLike = k.includes('commission') || k.includes('earning') || k.includes('payout') || k.includes('remuneration') || k.includes('reward');
    if (looksCommissionLike) {
      const n = safeNum(value);
      if (n > 0) out.push(n);
    }
    if (value && typeof value === 'object') collectCommissionLikeNumbers(value, out, depth + 1);
  }
}

function pickDigitalWalletAmount(item) {
  const amountObj = (item.amount && typeof item.amount === 'object')
    ? item.amount
    : ((item.value && typeof item.value === 'object') ? item.value : {});
  const typeText = String(item.type || item.transactionType || item.walletType || '').toLowerCase();
  const applyWalletSign = (value) => {
    const parsed = safeNum(value);
    if (parsed === 0) return 0;
    if ((typeText.includes('withdraw') || typeText.includes('debit')) && parsed > 0) {
      return -parsed;
    }
    return parsed;
  };
  const directCandidates = [
    amountObj.publisherValue,
    amountObj.programValue,
    amountObj.publisherAmount,
    amountObj.programAmount,
    amountObj.value,
    amountObj.amount,
    amountObj.netAmount,
    amountObj.grossAmount,
    amountObj.total,
    amountObj.totalAmount,
    item.publisherValue,
    item.programValue,
    item.digitalWallet,
    item.digitalWallets,
    item.digital_wallet,
    item.digital_wallets,
    item.digitalWalletAmount,
    item.digitalWalletCommission,
    item.digitalWalletEarnings,
    item.walletAmount,
    item.walletCommission,
    item.walletEarnings,
    item.amountValue,
    item.amount,
    item.value,
    item.commission,
    item.commissionValue,
    item.commissionAmount,
    item.publisherCommission,
    item.publisher_commission,
    item.pubCommission,
    item.publisherAmount,
    item.paymentAmount,
    item.payableAmount,
    item.netAmount,
    item.grossAmount,
    item.balance,
    item.invoicedAmount,
    item.paidAmount,
    item.total,
    item.totalAmount
  ];
  for (const candidate of directCandidates) {
    const signed = applyWalletSign(candidate);
    if (signed !== 0) return signed;
  }
  return applyWalletSign(findNumericByKeys(item, [
    'publisherValue',
    'programValue',
    'digitalWallet',
    'digitalWallets',
    'digital_wallet',
    'digital_wallets',
    'digitalWalletAmount',
    'digitalWalletCommission',
    'digitalWalletEarnings',
    'walletAmount',
    'walletCommission',
    'walletEarnings',
    'amount',
    'amountValue',
    'value',
    'commission',
    'commissionValue',
    'commissionAmount',
    'publisherCommission',
    'publisher_commission',
    'pubCommission',
    'publisherAmount',
    'paymentAmount',
    'payableAmount',
    'netAmount',
    'grossAmount',
    'balance',
    'invoicedAmount',
    'paidAmount',
    'total',
    'totalAmount'
  ]));
}

function buildProgramKey(item) {
  const programId = pickProgramId(item);
  if (programId) return 'program:' + programId;
  const programName = pickProgramName(item, '').toLowerCase();
  if (programName) return 'name:' + programName;
  const sourceId = pickSourceId(item);
  if (sourceId) return 'source:' + sourceId;
  return '';
}

function mergeDigitalWalletRows(metricRows, walletRows) {
  const walletByKey = new Map();

  for (const wallet of walletRows || []) {
    if (!wallet || typeof wallet !== 'object') continue;
    const key = buildProgramKey(wallet);
    if (!key) continue;
    const digitalWalletAmount = pickDigitalWalletAmount(wallet);
    if (digitalWalletAmount === 0) continue;
    const programId = pickProgramId(wallet);
    const existing = walletByKey.get(key) || {
      programId: programId || '-',
      programName: pickProgramName(wallet, programId),
      sourceId: pickSourceId(wallet),
      digitalWalletAmount: 0,
    };
    existing.digitalWalletAmount += digitalWalletAmount;
    walletByKey.set(key, existing);
  }

  const merged = (metricRows || []).map((row) => {
    const key = buildProgramKey(row || {});
    const wallet = key ? walletByKey.get(key) : null;
    if (!wallet) return row;
    walletByKey.delete(key);
    const existingDigitalWallet = safeNum(row.digitalWalletAmount || row.digitalWallet || row.walletAmount);
    const mergedDigitalWallet = existingDigitalWallet + wallet.digitalWalletAmount;
    return {
      ...row,
      digitalWalletAmount: mergedDigitalWallet,
      digitalWallet: mergedDigitalWallet,
      walletAmount: mergedDigitalWallet,
      totalCommission: safeNum(row.totalCommission) + wallet.digitalWalletAmount,
      amount: {
        ...(row.amount && typeof row.amount === 'object' ? row.amount : {}),
        digitalWallet: mergedDigitalWallet,
        digitalWalletAmount: mergedDigitalWallet
      }
    };
  });

  for (const wallet of walletByKey.values()) {
    merged.push({
      programId: wallet.programId,
      programName: wallet.programName,
      sourceId: wallet.sourceId,
      clicks: 0,
      sales: 0,
      orderValue: 0,
      publisherCommission: 0,
      totalCommission: wallet.digitalWalletAmount,
      digitalWalletAmount: wallet.digitalWalletAmount,
      digitalWallet: wallet.digitalWalletAmount,
      walletAmount: wallet.digitalWalletAmount,
    });
  }

  return merged;
}

function findDigitalWalletValue(item, commissionObj, totalCommission, publisherCommission) {
  const directCandidates = [
    item.digitalWallet,
    item.digitalWallets,
    item.digital_wallet,
    item.digital_wallets,
    item.digitalWalletAmount,
    item.digitalWalletCommission,
    item.digitalWalletEarnings,
    item.wallet,
    item.walletAmount,
    commissionObj.digitalWallet,
    commissionObj.digitalWallets,
    commissionObj.digital_wallet,
    commissionObj.digital_wallets,
    commissionObj.digitalWalletAmount,
    commissionObj.digitalWalletCommission,
    commissionObj.digitalWalletEarnings,
    findNumericByKeys(item, [
      'digitalWallet',
      'digitalWallets',
      'digital_wallet',
      'digital_wallets',
      'digitalWalletAmount',
      'digitalWalletCommission',
      'digitalWalletEarnings',
      'wallet',
      'walletAmount',
      'walletCommission',
      'walletEarnings',
    ])
  ];
  for (const candidate of directCandidates) {
    const parsed = safeNum(candidate);
    if (parsed !== 0) return parsed;
  }
  const inferredDigitalWallet = safeNum(totalCommission) - safeNum(publisherCommission);
  return inferredDigitalWallet > 0 ? inferredDigitalWallet : 0;
}

function parseMetrics(item) {
  if (item && typeof item === 'object') {
    const cached = METRICS_CACHE.get(item);
    if (cached) return cached;
  }

  const commissionObj = (item.salesCommission && typeof item.salesCommission === 'object')
    ? item.salesCommission
    : ((item.commission && typeof item.commission === 'object') ? item.commission : {});
  const commissionValue = (typeof item.commission === 'number' || typeof item.commission === 'string')
    ? safeNum(item.commission)
    : 0;

  const clicks = safeNum(item.clicks);
  const sales = safeNum(item.sales) + safeNum(item.iSales);
  const orderValue = Math.max(
    safeNum(item.orderValue),
    safeNum(item.salesOrderValue),
    safeNum(item.iSalesOrderValue),
    safeNum(item.eventOrderValue)
  );

  const directPublisherCommission = Math.max(
    safeNum(item.publisherCommission),
    safeNum(commissionObj.publisherCommission),
    findNumericByKeys(item, [
      'publisherCommission',
      'publisher_commission',
      'pubCommission',
      'publisherEarnings',
      'publisherReward',
      'eventPublisherCommission',
      'eventCommission',
      'salesCommissionPublisher',
      'commissionAmount',
      'commissionValue',
    ])
  );

  const directTotalCommission = Math.max(
    safeNum(item.totalCommission),
    safeNum(commissionObj.totalCommission),
    findNumericByKeys(item, [
      'totalCommission',
      'total_commission',
      'commissionTotal',
      'totalEarnings',
      'totalPayout',
      'networkCommission',
      'advertiserCommission',
      'salesCommissionTotal',
    ])
  );

  const discoveredCommissionNumbers = [];
  collectCommissionLikeNumbers(item.salesCommission, discoveredCommissionNumbers);
  collectCommissionLikeNumbers(item.commission, discoveredCommissionNumbers);
  // Full-row recursive scan removed; direct fields and commission subobjects are already checked.
  const discoveredCommissionMax = discoveredCommissionNumbers.length ? Math.max(...discoveredCommissionNumbers) : 0;

  const publisherCommission = Math.max(
    directPublisherCommission,
    commissionValue,
    discoveredCommissionMax
  );

  const totalCommission = Math.max(
    directTotalCommission,
    commissionValue,
    discoveredCommissionMax,
    publisherCommission
  );
  const digitalWallet = findDigitalWalletValue(item, commissionObj, totalCommission, publisherCommission);
  const totalEarnings = publisherCommission + digitalWallet;

  const metrics = { clicks, sales, orderValue, publisherCommission, totalCommission, digitalWallet, totalEarnings };
  if (item && typeof item === 'object') METRICS_CACHE.set(item, metrics);
  return metrics;
}

