function formatSharePercentages(values) {
  const nums = values.map((value) => Math.max(0, safeNum(value)));
  const total = nums.reduce((sum, value) => sum + value, 0);
  if (total <= 0) return nums.map(() => '0%');

  const exact = nums.map((value) => (value / total) * 100);
  const rounded = exact.map((value) => Math.floor(value));
  let remaining = 100 - rounded.reduce((sum, value) => sum + value, 0);

  exact
    .map((value, index) => ({
      index,
      remainder: value - rounded[index],
      value: nums[index],
    }))
    .sort((a, b) => {
      const byRemainder = b.remainder - a.remainder;
      if (byRemainder !== 0) return byRemainder;
      const byValue = b.value - a.value;
      if (byValue !== 0) return byValue;
      return a.index - b.index;
    })
    .forEach((entry) => {
      if (remaining <= 0) return;
      rounded[entry.index] += 1;
      remaining -= 1;
    });

  return rounded.map((value) => value + '%');
}

function buildTopProgramsCompetitorPerformanceTable() {
  const primaryLabel = String(
    payload.clientName ||
    payload.programName ||
    payload.clientUsername ||
    'Primary Publisher'
  ).trim() || 'Primary Publisher';
  const competitorLabels = ['Comp. A', 'Comp. B', 'Comp. C', 'Comp. D'];
  const byProgram = new Map();

  const ensureProgram = (program) => {
    if (!program || !program.key) return null;
    if (!byProgram.has(program.key)) {
      byProgram.set(program.key, {
        key: program.key,
        programName: program.programName || program.programId || program.key,
        values: [0, 0, 0, 0, 0],
      });
    }
    return byProgram.get(program.key);
  };

  currentPrograms.forEach((program) => {
    const row = ensureProgram(program);
    if (!row) return;
    row.values[0] += program.publisherCommission;
  });

  competitorProgramGroups.slice(0, 4).forEach((group, groupIndex) => {
    group.programs.forEach((program) => {
      const row = ensureProgram(program);
      if (!row) return;
      row.values[groupIndex + 1] += program.publisherCommission;
    });
  });

  const rows = Array.from(byProgram.values())
    .map((row) => ({
      ...row,
      primaryCommission: row.values[0],
      totalCommission: row.values.reduce((sum, value) => sum + value, 0),
    }))
    .filter((row) => row.totalCommission > 0);

  const primaryRows = rows.filter((row) => row.primaryCommission > 0);
  const candidateRows = primaryRows.length >= TOP_PROGRAM_COMPETITOR_LIMIT ? primaryRows : rows;

  return candidateRows
    .sort((a, b) => {
      const byPrimaryCommission = b.primaryCommission - a.primaryCommission;
      if (byPrimaryCommission !== 0) return byPrimaryCommission;
      const byTotalCommission = b.totalCommission - a.totalCommission;
      if (byTotalCommission !== 0) return byTotalCommission;
      return a.programName.localeCompare(b.programName);
    })
    .slice(0, TOP_PROGRAM_COMPETITOR_LIMIT)
    .map((row) => {
      const shares = formatSharePercentages(row.values);
      return {
        'Program Name': row.programName,
        [primaryLabel]: shares[0],
        ...Object.fromEntries(competitorLabels.map((label, index) => [label, shares[index + 1]])),
      };
    });
}

