function pctOf(value, total) {
  const denominator = safeNum(total);
  if (denominator <= 0) return 0;
  return (safeNum(value) / denominator) * 100;
}

function severityFromShare(sharePct) {
  if (sharePct >= 60) return 'High';
  if (sharePct >= 45) return 'Medium';
  return 'Low';
}

function severityFromMovement(absValue, pctValue) {
  const magnitude = Math.abs(safeNum(absValue));
  const pct = Math.abs(Number(pctValue));
  if (magnitude >= 1000 || pct >= 40) return 'High';
  if (magnitude >= 250 || pct >= 20) return 'Medium';
  return 'Low';
}

function topProgramForMetric(metricName) {
  return currentPrograms
    .filter((r) => safeNum(r[metricName]) > 0)
    .sort((a, b) => safeNum(b[metricName]) - safeNum(a[metricName]))[0] || null;
}

function makeRiskRow(severity, title, analysis) {
  return {
    Issue: severity + ' - ' + title,
    Analysis: analysis,
  };
}

function addRisk(rows, seen, severity, title, analysis) {
  const key = title.toLowerCase();
  if (seen.has(key)) return;
  seen.add(key);
  rows.push(makeRiskRow(severity, title, analysis));
}

