  const statusId = pick(row, ['statusId', 'statusID', 'Status ID']);
  const programId = pick(row, ['id', 'programId', 'programID', 'Program ID']);
  const name = pick(row, ['name', 'programName', 'Program Name']);
  const createdDate = pick(row, ['createdDate', 'Created Date']);
  const statusName = pick(row, ['statusName', 'Status Name', 'status']);
  return {
    id: compactScalar(programId),
    name: compactScalar(name),
    createdDate: compactScalar(createdDate),
    statusId: compactScalar(statusId),
    connectionStatus: statusLabel(statusId, statusName),
  };
}

let rows = [];
if (Array.isArray(response)) rows = response;
else if (Array.isArray(response.items)) rows = response.items;
else if (Array.isArray(response.data)) rows = response.data;
else if (Array.isArray(response.rows)) rows = response.rows;
else if (response && typeof response === 'object' && !Array.isArray(response)) rows = [response];

const compactRows = rows.map(compactProgram).filter((row) => row && (row.id || row.name));

return [{
  json: {
    rows: compactRows,
    rowCount: compactRows.length,
  },
}];
